-- F-01 link-access-foundation: the single dinner event and its link keys.
--
-- One row only (singleton): the app runs exactly one dinner (PRD Non-Goals: no multiple events).
-- organizer_key opens /o/<key> (everything), tv_key opens /tv/<key> (read-only seating view).
-- Keys are 18 random bytes in base64url (24 chars, 144 bits) generated by the server (src/lib/access/keys.ts).
--
-- Access model: the browser never talks to the database. All reads and writes go through the Astro server with
-- the service-role key, which bypasses RLS. RLS is enabled with no policies and table privileges are revoked
-- from the anon/authenticated roles, so the public REST API exposes nothing.

create table public.event (
  id smallint primary key default 1,
  name text not null default 'Kolacja podwyżkowa',
  organizer_key text not null unique,
  tv_key text not null unique,
  created_at timestamptz not null default now(),
  constraint event_singleton check (id = 1),
  constraint event_keys_distinct check (organizer_key <> tv_key),
  constraint event_organizer_key_format check (organizer_key ~ '^[A-Za-z0-9_-]{24}$'),
  constraint event_tv_key_format check (tv_key ~ '^[A-Za-z0-9_-]{24}$')
);

comment on table public.event is 'The single dinner event (singleton) with its organizer and TV link keys.';

alter table public.event enable row level security;

revoke all on table public.event from anon, authenticated;
